import{z as n,x as s,o as e,c as d,q as r,j as i,D as E,d as l,s as B,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"对数似然对生成式评测","description":"","frontmatter":{"title":"对数似然对生成式评测","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/loglik-vs-generative-eval.md","filePath":"llm/loglik-vs-generative-eval.md","lastUpdated":1791063341000}'),p={name:"llm/loglik-vs-generative-eval.md"};function m(h,a,c,D,u,F){const o=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="对数似然对生成式评测" tabindex="-1">对数似然对生成式评测 <a class="header-anchor" href="#对数似然对生成式评测" aria-label="Permalink to &quot;对数似然对生成式评测&quot;">​</a></h1><div class="epigraph"><p>选择题可以不生成一个字母：比较各选项续写的对数概率即可。那测的是条件似然，不是模型在对话里会写出什么。</p><footer>—— 对照 EleutherAI 评测套件与 HELM 对 completion / likelihood 协议的区分</footer></div><p><a href="/llm/perplexity-eval-pitfalls">上一课</a>把 PPL 从能力声明里拿掉。缺口立刻出现：<a href="/llm/mmlu">MMLU</a> 一类卷面仍常按选项对数似然计分，而产品走的是采样生成。本课钉这两种协议不可互换。后课提示格式敏感默认：你已经知道「同一个准确率」可能来自完全不同的解码器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对数似然协议：把题干当前缀，对每个选项算 \\(\\log p(y_i\\mid x)\\)（或长度归一后的平均），取最大者。优点是对基座稳、省解码、可微近似分类。缺点是模型从未被要求「只输出 B」；聊天模型还可能先道歉再给答案，似然协议看不见这条路径。<span class="marginnote">术语翻译：似然协议用的是「教师强迫」——像考试时把每句候选答案都印在卷子上，只问『这句话接在题干后面像不像你写的』，全程不许模型自己动笔。它测的是欣赏力（给文本打分），不是表达力（自己写出答案）。</span></p><p>生成式协议：让模型自由续写，再从文本里抽答案。它更接近产品，但耦合温度、最大长度、停止符、抽取器。Gao 等人的 lm-eval 把两套都实现了，同一模型在同一科目上可以差出数个点——那不是随机噪声，是仪器。</p><p><span class="marginnote">指令模型用似然协议时，必须决定：选项要不要带聊天模板、要不要在「Answer:」之后再算续写概率。模板一变，似然排名就变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写报告先锁协议名：<code>loglikelihood</code> 还是 <code>generate_until</code>。似然侧要声明：是否按 token 数归一、是否把选项字母与选项文本一起条件、是否忽略公共前缀。生成侧要声明：温度、top-\\(p\\)、停止串、是否只看第一个字母。</p><p>基座对比优先似然，避免「还不会按格式答题」被算成无知。对话模型与产品声明优先生成。两套都跑时分表，禁止平均成一个「MMLU」。<span class="marginnote">常见误区：初学者常把两套分数直接放进同一列比大小，甚至取平均。它们更像笔试与路考：同一考生笔试 90 分路考挂科完全正常。报告里写「MMLU 88」而不注明是 <code>loglikelihood</code> 还是 <code>generate_until</code>，这个数字无法复核，也无法与别人的 88 比较。</span></p>',10)),(e(),i(A,null,{default:E(()=>[B(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%A2%98%E5%B9%B2%20x%22%5D%20--%3E%20LL%5B%22%E5%90%84%E9%80%89%E9%A1%B9%20log%20p%22%5D%0A%20%20Q%20--%3E%20GEN%5B%22%E9%87%87%E6%A0%B7%E7%94%9F%E6%88%90%22%5D%0A%20%20LL%20--%3E%20Y1%5B%22argmax%20%E9%80%89%E9%A1%B9%22%5D%0A%20%20GEN%20--%3E%20EX%5B%22%E6%8A%BD%E5%8F%96%E7%AD%94%E6%A1%88%22%5D%0A%20%20Y1%20--%3E%20ACC%5B%22%E5%87%86%E7%A1%AE%E7%8E%87%22%5D%0A%20%20EX%20--%3E%20ACC%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"似然协议问的是：在教师强迫的前缀下，哪一段续写更像训练分布。生成协议问的是：自回归采样路径能否落到可抽取的正确槽里。前者对「会但说不出来」友好，后者对「会说但校准差、爱解释」惩罚。对齐后的模型常常生成更好、裸似然更乱，因为 RLHF 改的是采样路径上的偏好，不一定抬高选项续写的相对似然。",-1)),(e(),i(A,null,{default:E(()=>[B(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20A%5B%22RLHF%20%E5%AF%B9%E9%BD%90%3Cbr%2F%3E%E6%94%B9%E7%9A%84%E6%98%AF%E9%87%87%E6%A0%B7%E8%B7%AF%E5%BE%84%E5%81%8F%E5%A5%BD%22%5D%0A%20%20A%20--%3E%20G%5B%22%E7%94%9F%E6%88%90%E5%8D%8F%E8%AE%AE%E8%B5%B0%E9%87%87%E6%A0%B7%E8%B7%AF%E5%BE%84%3Cbr%2F%3E%E5%AF%B9%E9%BD%90%E7%BA%A2%E5%88%A9%E7%9B%B4%E6%8E%A5%E5%8F%AF%E8%A7%81%22%5D%0A%20%20A%20--%3E%20L%5B%22%E4%BC%BC%E7%84%B6%E5%8D%8F%E8%AE%AE%E8%B5%B0%E6%95%99%E5%B8%88%E5%BC%BA%E8%BF%AB%3Cbr%2F%3E%E7%BB%95%E8%BF%87%E9%87%87%E6%A0%B7%E8%B7%AF%E5%BE%84%22%5D%0A%20%20G%20--%3E%20HG%5B%22%E7%94%9F%E6%88%90%E5%87%86%E7%A1%AE%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20L%20--%3E%20HL%5B%22%E9%80%89%E9%A1%B9%E4%BC%BC%E7%84%B6%E6%8E%92%E5%BA%8F%E5%8F%AF%E8%83%BD%E6%9B%B4%E4%B9%B1%22%5D%0A%20%20HG%20--%3E%20D%5B%22%E5%90%8C%E4%B8%80%E6%A8%A1%E5%9E%8B%2C%20%E4%B8%A4%E5%A5%97%E5%88%86%E6%95%B0%E5%88%86%E5%8F%89%3Cbr%2F%3E%E5%8F%AA%E8%83%BD%E5%88%86%E8%A1%A8%2C%20%E4%B8%8D%E8%83%BD%E5%B9%B3%E5%9D%87%22%5D%0A%20%20HL%20--%3E%20D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>长度归一是隐性先验：不归一则长选项吃亏（多项连乘）；归一则短而含糊的干扰项可能被抬高。<span class="marginnote">数字实例：选项 A「Paris」1 个 token，\\(\\log p=-2\\)；选项 B「Paris, a city in France」6 个 token，每个平均 \\(-1.5\\)，合计 \\(-9\\)。不归一时 A（\\(-2\\gt-9\\)）胜出；改成按长度平均后 A 是 \\(-2\\)、B 是 \\(-1.5\\)，B 反超。归一与否直接改变答案，所以必须写进协议。</span>必须写进协议，不能当实现细节。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>代码与数学的 pass / 精确匹配只能走生成（再执行）。下一课提示格式敏感会说明：哪怕锁死了似然还是生成，空格与冒号仍能改排名。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>选项似然与生成抽取是两套考试，准确率不能横比。</li><li>基座用似然，产品声明用生成；并存必须分表。</li><li>对齐可以抬生成、搅乱裸似然。</li><li>出处：EleutherAI lm-evaluation-harness；Liang 等 HELM；MMLU 原文的 few-shot 设定。</li></ul>',5))])}const f=n(p,[["render",m]]);export{g as __pageData,f as default};
